import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    me, opp = history[-1]

    opp_c = 0
    for h in history:
        if h[1] == 'C':
            opp_c += 1
    opp_d = n - opp_c
    coop_rate = opp_c / float(n)

    # Strong defector: limit losses.
    if opp_d >= 8 and coop_rate < 0.25:
        return 'D'

    # Long cooperative relationship: keep it alive, mild probing near end.
    if coop_rate >= 0.9 and n >= 6:
        if n >= 96 and opp == 'C':
            return 'D'
        return 'C'

    # Count recent opponent defections.
    recent_d = 0
    k = min(6, n)
    for i in range(n - k, n):
        if history[i][1] == 'D':
            recent_d += 1

    # Respond to a defection with mostly defection, but keep a repair chance.
    if opp == 'D':
        # Immediate retaliation, unless partner has been very cooperative overall.
        if recent_d >= 2:
            return 'D'
        if coop_rate >= 0.7:
            # occasional quick forgiveness to break retaliation cycles
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just cooperated.
    if recent_d >= 3:
        # Recent trouble, but cooperation now: punish lightly then forgive.
        if rng.random() < 0.55:
            return 'C'
        return 'D'

    if recent_d >= 1:
        # Isolated defections in an otherwise cooperative match: forgive.
        return 'C'

    return 'C'
